import json

def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    # Find the vertical column where ALL non-zero values are 5
    vertical_col = None
    for col in range(w):
        vals = [grid[r][col] for r in range(h)]
        non_zero = [v for v in vals if v != 0]
        if all(v == 5 for v in non_zero):
            if len(non_zero) >= 2:
                vertical_col = col
                non_zero_rows = [r for r in range(h) if grid[r][col] != 0]
                break

    if vertical_col is None:
        return grid

    # Find all horizontal bars on rows of the vertical bar
    horizontal_bars = []
    for row in non_zero_rows:
        start = None
        end = None
        for col in range(vertical_col + 1, w):
            val = grid[row][col]
            if start is None and val != 0:
                start = col
            if start is not None and val == 0:
                end = col
                break
        if start is not None:
            if end is None:
                end = w
            horizontal_bars.append((row, start, end, grid[row][start:end]))

    if not horizontal_bars:
        return grid

    # Sort horizontal bars by row
    horizontal_bars.sort()

    result = [row[:] for row in grid]

    # Case 1: Only one horizontal bar -> fill from top of vertical bar to that bar
    if len(horizontal_bars) == 1:
        _, start, end, pat = horizontal_bars[0]
        top_row = non_zero_rows[0]
        for r in range(top_row, horizontal_bars[0][0]):
            for c in range(start, end):
                result[r][c] = pat[c - start]
    else:
        # Case 2: Multiple bars -> alternating pattern based on row parity
        for r in non_zero_rows:
            if grid[r][vertical_col + 1] == 0:
                same_parity_bars = [(rb, ps, pe, pat) for rb, ps, pe, pat in horizontal_bars if rb % 2 == r % 2]
                if same_parity_bars:
                    _, ps, pe, pat = same_parity_bars[0]
                    for c in range(ps, pe):
                        result[r][c] = pat[c - ps]

    return result

